+let mode='title',room={x:0,y:0,w:1100,h:780},player={x:550,y:390,r:15,hp:100,max:100,speed:225,faceX:1,faceY:0,attack:0,dash:0,dashCd:0,ifr:0,combo:0,comboTime:0,damageFlash:0},enemies=[],particles=[],hazards=[],echoes=[],keys={},run={floor:1,kills:0,ash:0,perma:+localStorage.getItem('rbBlood')||0,slots:{arms:null,legs:null,torso:null},roomKills:0,rooms:0,weapon:0,upgradeHp:0},lastAttack={x:1,y:0,time:0},dark=0,shake=0,altar={x:550,y:120,active:true},mapStage=0,selectedBiome=0,audio=null;
