function doAttack(){if(mode!=='play'||player.attack>0)return;player.attack=player.slots.arms?.id==='scythe'?.48:player.slots.arms?.id==='talons'?.22:.34;player.comboTime=2.2;player.combo++;lastAttack={x:player.faceX,y:player.faceY,time:now};let rune=player.slots.arms?.id||'flesh';if(rune==='scythe'&&player.hp<=5){toast('Not enough blood to carve.');return}if(rune==='scythe')player.hp-=5;if(rune==='talons')player.hp=Math.min(player.max,player.hp+1);let range=rune==='scythe'?100:rune==='talons'?75:64,angle=Math.atan2(player.faceY,player.faceX),hit=0;
 if(rune==='bolt'){let target=enemies.filter(e=>!e.dead).sort((a,b)=>dist(player,a)-dist(player,b))[0];if(target&&dist(player,target)<400){target.hp-=2+Math.floor(player.combo/6);target.hit=.2;burst(target.x,target.y,'#9b72e9',12);hit=1}else{for(let a=0;a<3;a++)particles.push({x:player.x,y:player.y,vx:Math.cos(angle)*380,vy:Math.sin(angle)*380,life:.36,max:.36,color:'#a77aea',r:4,bolt:true})}}
 else enemies.forEach(e=>{let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),diff=Math.atan2(dy,dx)-angle;while(diff>Math.PI)diff-=Math.PI*2;while(diff<-Math.PI)diff+=Math.PI*2;if(d<range+e.r&&Math.abs(diff)<(rune==='scythe'?1.5:1.0)){e.hp-=rune==='scythe'?3:1+(player.combo>5?1:0);e.hit=.24;hit++;burst(e.x,e.y,rune==='scythe'?'#f05a70':'#d7c6ba',5)}});
 if(hit){player.combo=Math.min(12,player.combo);player.comboTime=2.5;sound(rune==='scythe'?75:125,.11,'sawtooth',.045)}else sound(170,.07,'triangle',.02);if(player.slots.arms)player.combo=Math.min(12,player.combo);syncHud()}
function dash(){if(mode!=='play'||player.dashCd>0)return;let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0),dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0);if(!dx&&!dy){dx=player.faceX;dy=player.faceY}let n=Math.hypot(dx,dy)||1;player.dash=.2;player.ifr=player.slots.legs?.id==='wraith'?.37:.25;player.dashCd=player.slots.legs?.id==='wraith'?.65:1.05;player.dx=dx/n;player.dy=dy/n;player.dashV=player.slots.legs?.id==='glide'?780:690;player.comboTime=Math.max(player.comboTime,1.7);sound(85,.18,'triangle',.05);for(let i=0;i<12;i++)burst(player.x+rand(-9,9),player.y+rand(-10,10),'#a76cd2',1);if(player.slots.torso?.id==='echo')echoes.push({x:player.x,y:player.y,life:.65,done:false});if(player.slots.legs?.id==='parasite')enemies.forEach(e=>{if(!e.dead&&dist(e,{x:player.x+player.dx*50,y:player.y+player.dy*50})<e.r+28){e.hp-=1;player.hp=Math.min(player.max,player.hp+10);burst(e.x,e.y,'#ed526a',8)}})}
function burst(x,y,color,n=8){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),v=rand(30,180),life=rand(.22,.62);particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life,max:life,color,r:rand(1,4)})}}
function hurt(amount){if(player.ifr>0)return;player.hp-=amount;player.damageFlash=.35;player.combo=0;player.comboTime=0;shake=9;sound(55,.24,'square',.05);if(player.hp<=0)die()}
function die(){run.perma+=Math.max(4,Math.floor(run.kills*1.6)+run.floor*2);localStorage.setItem('rbBlood',run.perma);mode='death';hud.style.display='none';panel(`<div class="eyebrow">The abyss has claimed another vessel</div><h2 class="title">Flesh <span>unmade.</span></h2><p class="subtitle">Your carved runes and ${run.ash} Soul Ash are lost to the dark. Your blood remembers.</p><div class="meta" style="margin:20px 0">PETRIFIED BLOOD RECOVERED &nbsp;◆&nbsp; ${run.perma}</div><p class="small">You reached floor ${run.floor} · felled ${run.kills} creatures.</p><div class="row"><button class="btn" id="again">DESCEND AGAIN</button><button class="btn secondary" id="sanct">SHATTERED SANCTUARY</button></div>`);document.querySelector('#again').onclick=startRun;document.querySelector('#sanct').onclick=sanctuary}
function chooseRune(){let slot=['arms','legs','torso'][Math.floor(Math.random()*3)],offers=[...RUNES[slot]].sort(()=>Math.random()-.5).slice(0,3);mode='rune';setMode('rune');panel(`<div class="eyebrow">The altar opens · carve a rune into your ${slot}</div><h2 class="title" style="font-size:36px">Choose your <span>scar.</span></h2><p class="subtitle">Power is never free. Your flesh remembers every bargain.</p><div class="choices">${offers.map((r,i)=>`<div class="choice" data-choice="${i}"><div class="tag" style="color:${r.color}">${r.type}</div><h3>${r.name}</h3><p>${r.desc}</p></div>`).join('')}</div><div class="small">CONTROLS: WASD Move · Space Attack · Shift Dash · E interact</div>`);overlay.querySelectorAll('[data-choice]').forEach((el,i)=>el.onclick=()=>{carve(slot,offers[i]);mapScreen()})}
function carve(slot,r){if(slot==='arms'&&player.slots.arms?.id==='scythe')player.max+=5;if(r.id==='husk'){player.max+=35;player.hp+=35;player.speed*=.85}if(r.id==='lantern'){player.max-=15;player.hp=Math.min(player.hp,player.max)}if(r.id==='scythe')player.max-=10;if(player.slots[slot]){player.max+=player.slots[slot].id==='scythe'?10:0}player.slots[slot]=r;player.hp=Math.min(player.hp,player.max);toast(`${r.name} carved into ${slot}.`);syncHud()}
