function altarInteract(){if(!altar.active)return;altar.active=false;run.ash+=18+run.floor*4;mode='altar';setMode('altar');panel(`<div class="eyebrow">ALTAR OF ${biome().name}</div><h2 class="title" style="font-size:38px">The altar <span>hungers.</span></h2><p class="subtitle">A black stone dais drinks the light. The air speaks in the voices of your dead.</p><div class="meta" style="margin:18px 0">SOUL ASH GATHERED &nbsp;◆&nbsp; ${run.ash}</div><div class="row"><button class="btn" id="carve">CARVE A BODY RUNE</button><button class="btn secondary" id="leave">LEAVE THE ALTAR</button></div><p class="small">Carving replaces the rune in that body slot. The cost is permanent for this run.</p>`);document.querySelector('#carve').onclick=chooseRune;document.querySelector('#leave').onclick=mapScreen}
function syncHud(){document.querySelector('#hptext').textContent=`${Math.max(0,Math.ceil(player.hp))} / ${player.max}`;document.querySelector('#hpbar').style.width=`${clamp(player.hp/player.max*100,0,100)}%`;document.querySelector('#momentum').style.width=`${player.combo/12*100}%`;document.querySelector('#ash').textContent=run.ash;document.querySelector('#floor').textContent=['I','II','III','IV','V','VI','VII','VIII','IX'][Math.min(8,run.floor-1)]||run.floor;document.querySelector('#kills').textContent=run.kills+run.roomKills;document.querySelector('#armSlot').textContent=player.slots.arms?.name||'Fleshbound';document.querySelector('#legSlot').textContent=player.slots.legs?.name||'Gravewalk';document.querySelector('#torsoSlot').textContent=player.slots.torso?.name||'Hollow';document.querySelector('#objective').innerHTML=`<b>${biome().name}</b><br>${enemies.length?'Silence the altar':altar.active?'Approach the altar · E':'The altar is quiet'}`}

